import{_ as a}from"./chunks/daily-2026-08-10-authority-plane-cascade-containment-figure.B7bN8IO2.js";import{_ as r,C as n,o as i,c as o,E as s,a2 as c}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"Multi-Agent Recovery Needs an Authority Plane, Not Blind Retry","description":"","frontmatter":{"title":"Multi-Agent Recovery Needs an Authority Plane, Not Blind Retry","date":"2026-08-10","column":"industry-architecture","category":"daily","summary":"Controlled failure-injection evidence shows that retry can recover transient tool faults but cannot repair latent semantic corruption when the same bad state remains authoritative; reliable containment therefore needs an independent state-authority and provenance plane.","sources":["research/analysis/Q-20260810-02-authoritative-state-containment.md","research/reading/Q-20260810-02-trusted-state-cascade-containment.md"],"item_id":"Q-20260810-02","lifecycle":"Published","source_research_object":"research/analysis/Q-20260810-02-authoritative-state-containment.md","source_reading_result":"research/reading/Q-20260810-02-trusted-state-cascade-containment.md","cover":"/assets/covers/daily-2026-08-10-authority-plane-cascade-containment.webp","visualization":"/assets/covers/daily-2026-08-10-authority-plane-cascade-containment-figure.svg","visualization_decision":"Required — dedicated editorial Article Cover passes Cover Gate; explanatory Article Figure retained separately","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"en/industry/2026-08-10-authority-plane-cascade-containment.md","filePath":"en/industry/2026-08-10-authority-plane-cascade-containment.md","lastUpdated":1786455299000}'),d={name:"en/industry/2026-08-10-authority-plane-cascade-containment.md"};function l(h,e,u,p,m,y){const t=n("ArticleCover");return i(),o("div",null,[s(t,{image:"/assets/covers/daily-2026-08-10-authority-plane-cascade-containment.webp",kicker:"Industry Architecture · Daily Research",title:"Multi-Agent Recovery Needs an Authority Plane, Not Blind Retry",summary:"Controlled failure-injection evidence shows that retry can recover transient tool faults but cannot repair latent semantic corruption when the same bad state remains authoritative; reliable containment therefore needs an independent state-authority and provenance plane.",version:"Q-20260810-02",status:"Daily Runtime V5 · 2026-08-10",languageHref:"/zh/industry/2026-08-10-authority-plane-cascade-containment",languageLabel:"中文"}),e[0]||(e[0]=c('<h1 id="multi-agent-recovery-needs-an-authority-plane-not-blind-retry" tabindex="-1">Multi-Agent Recovery Needs an Authority Plane, Not Blind Retry <a class="header-anchor" href="#multi-agent-recovery-needs-an-authority-plane-not-blind-retry" aria-label="Permalink to &quot;Multi-Agent Recovery Needs an Authority Plane, Not Blind Retry&quot;">​</a></h1><p>When a multi-agent workflow fails, “retry” and “repair” are not the same operation. Retry can restore liveness after a transient tool fault. It cannot repair semantic corruption if every new attempt consumes the same corrupted state.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p><strong>The central judgment is that semantic recovery requires an authority plane: an independently represented lineage that tells workers which state is accepted, stale, quarantined or superseded.</strong> A reasoning agent may diagnose or propose a correction, but it should not be responsible for inventing both truth and repair policy from the same potentially corrupted context.</p><p>The completed Reading Result uses OrchestraBench as controlled evidence. Its strongest LLM containment result explicitly supplies trusted upstream state, and an ablation removing that signal collapses latent recovery close to baseline. The reusable lesson is therefore trusted-state reconciliation, not autonomous LLM self-healing.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>Production consumes the same-day Research Object <code>Q-20260810-02</code> and uses its completed Reading Result only for citation and evidence verification. The primary source is the OrchestraBench preprint.</p><ul><li>arXiv abstract: <a href="https://arxiv.org/abs/2608.05263" target="_blank" rel="noreferrer">https://arxiv.org/abs/2608.05263</a></li><li>Full text: <a href="https://arxiv.org/html/2608.05263v1" target="_blank" rel="noreferrer">https://arxiv.org/html/2608.05263v1</a></li></ul><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The paper separates transient tool faults from latent semantic/context faults. On its controlled staged computations, blind retry can recover the retryable tool-failure mode, while latent modes continue to propagate because the underlying state remains corrupted.</p><p>The depth experiment reports increasing cascade radius as latent faults pass through longer pipelines. More importantly, the policy-conditioned LLM receives a trusted upstream value and explicit permission to repair an anomaly. Removing that trusted-upstream signal materially reduces latent recovery. The authors themselves caution that this row is a trusted-state self-correction probe, not a deployment estimate for autonomous routing.</p><p><img src="'+a+'" alt="Authority-plane containment mechanism"></p><p><em>Figure 1. Trusted State and an independent Authority Plane jointly prevent a potentially bad state from cascading downstream. Source: Research Center synthesis based on the cited primary sources.</em></p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Recovery mechanism</th><th>What it changes</th><th>Works best for</th><th>Semantic corruption risk</th><th>Evidence status</th></tr></thead><tbody><tr><td>Blind retry</td><td>Repeats execution with essentially the same state</td><td>Transient/retryable tool faults</td><td>High when the bad state remains authoritative</td><td>Reported baseline mechanism in OrchestraBench</td></tr><tr><td>LLM repair without trusted upstream</td><td>Adds model reasoning but no independent truth signal</td><td>Diagnosis may improve in some cases</td><td>Model must infer truth from possibly corrupted context</td><td>Ablation drops latent recovery near baseline in the tested construct</td></tr><tr><td>Trusted-state repair</td><td>Adds an external correctness/reference signal</td><td>Latent/context repair in the controlled probe</td><td>Lower when the authority signal is valid</td><td>Stronger measured recovery in the paper&#39;s probe</td></tr><tr><td>Authority-plane reconciliation</td><td>Research Center architecture proposal: versioned provenance, accepted state, invalidation and selective recomputation</td><td>Long-lived production workflows</td><td>Depends on authority quality and conflict governance</td><td>Architectural inference, not measured by the paper</td></tr></tbody></table><p>The first three rows summarize the paper and completed Reading Result. The fourth is a Research Center architecture synthesis.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>Reliable orchestration should separate the <strong>reasoning plane</strong> from the <strong>authority plane</strong>. Agents can interpret, compare, plan and repair, but authoritative state should be represented independently through a versioned checkpoint, validated business fact, approved human decision, immutable event-log position or another source with explicit provenance.</p><p>This also changes how retry policies should be designed. A transport retry asks, “can the same operation succeed if attempted again?” A semantic repair asks, “which state is wrong, which state is authoritative, and which descendants must be invalidated?” Mixing those questions causes systems to repeatedly recompute from corrupted context.</p><p>In a branching workflow, cascade impact should not be measured only as linear distance. Production systems need provenance edges that identify which downstream outputs consumed which upstream state version, so recovery can invalidate only affected descendants rather than replaying the whole graph.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>For Digital Employees, preserve authoritative checkpoints for long-running jobs, especially human approvals and externally verified business facts. When inconsistency is detected, reconcile to a trusted state before rerunning downstream work.</p><p>For CodeFlowMu, add explicit state-version and provenance fields to workflow nodes. Downstream outputs should declare the upstream version they consumed. Separate transient retry policies from semantic repair policies, and record invalidated descendants so repair scope is observable.</p><p>For TMPA, the controlled benchmark is useful evidence for custody, provenance and reconciliation research, but it does not justify treating one benchmark&#39;s trusted-state probe as a protocol mandate.</p><h2 id="boundaries-and-uncertainty" tabindex="-1">Boundaries and uncertainty <a class="header-anchor" href="#boundaries-and-uncertainty" aria-label="Permalink to &quot;Boundaries and uncertainty&quot;">​</a></h2><p>OrchestraBench&#39;s core experiments are controlled mechanism probes, not measurements of full enterprise deployments. Some validation reframes the same staged computation in domain language rather than running a real business process. The strongest containment condition has an information advantage because trusted state is supplied explicitly. In production, that authority signal can itself be stale, conflicting or compromised and therefore needs governance of its own.</p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>The next engineering questions are: what qualifies as authoritative state for each Digital Employee job type; how competing authoritative checkpoints are reconciled; how provenance works across branching DAGs and asynchronous work; and how to measure the cost of attribution plus repair against rollback or human escalation.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The header cover uses a controlled barrier to represent containment of corrupted state by an authority plane. The mechanism figure embedded in the Observation section explains the relationship among trusted state, the authority plane and downstream cascade propagation. The two visual roles use different assets; no vendor artwork or invented quantitative data is used.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>OrchestraBench, arXiv preprint <code>2608.05263</code>: <a href="https://arxiv.org/abs/2608.05263" target="_blank" rel="noreferrer">https://arxiv.org/abs/2608.05263</a></li><li>OrchestraBench full text: <a href="https://arxiv.org/html/2608.05263v1" target="_blank" rel="noreferrer">https://arxiv.org/html/2608.05263v1</a></li><li>Research Center Research Object: <code>research/analysis/Q-20260810-02-authoritative-state-containment.md</code></li><li>Research Center Reading Result: <code>research/reading/Q-20260810-02-trusted-state-cascade-containment.md</code></li></ol><blockquote><p>Editing status: published. Trusted-state assumption, ablation interpretation, retry/repair distinction, limitations and bilingual evidence boundary checked.</p></blockquote>',33))])}const f=r(d,[["render",l]]);export{b as __pageData,f as default};
